/**
 * Spending Chart model (pure)
 *
 * Reshapes a `SpendingReport` into the flat bar list the chart renders. The chart
 * is an accordion: every Grouping shows as one bar, and any Grouping can be
 * expanded in place to reveal its Category bars while its siblings stay visible.
 * Multiple Groupings can be open at once — `expandedGroups` is a set.
 *
 * No rendering, no library types — a plain transform, unit-tested like
 * `buildSpendingReport`. The Svelte component owns colour, brackets, and the
 * expand/collapse toggles.
 *
 * Design: docs/plans/2026-07-09-spending-report-design.md
 */

import type { SpendingReport, GroupSection, Cell } from './spendingReport';

/** One bar: a collapsed Grouping (`kind: 'group'`) or a Category of an expanded Grouping. */
export interface ChartBar {
	/** x-axis label — the Grouping name (collapsed) or Category name (expanded). */
	name: string;
	/** Area of Importance this bar rolls up to; '' for Uncategorized. Drives colour + brackets. */
	importance: string;
	/** The Grouping this bar belongs to — the unit of expand/collapse. */
	groupName: string;
	kind: 'group' | 'category';
	/** Year-to-date total. */
	total: number;
	/** Amount per visible month, keyed by month label. Retained for a future trend view. */
	monthly: Record<string, number>;
}

export interface ChartModel {
	/** Visible month labels, in order. */
	months: string[];
	bars: ChartBar[];
}

const UNCATEGORIZED = 'Uncategorized';

/** Map a report row's month cells to a { monthLabel: amount } record. */
function cellsToMonthly(cells: Cell[], monthLabels: string[]): Record<string, number> {
	const monthly: Record<string, number> = {};
	for (let i = 0; i < monthLabels.length; i++) {
		monthly[monthLabels[i]] = cells[i]?.amount ?? 0;
	}
	return monthly;
}

/**
 * Build the chart model for the current expand state.
 *
 * @param report         The spending report for the selected year.
 * @param expandedGroups Grouping names currently expanded to their Categories.
 */
export function buildSpendingChart(
	report: SpendingReport,
	expandedGroups: ReadonlySet<string>
): ChartModel {
	const months = report.monthLabels;
	const bars: ChartBar[] = [];

	const pushGroup = (group: GroupSection, importance: string) => {
		if (expandedGroups.has(group.name)) {
			for (const row of group.rows) {
				bars.push({
					name: row.name,
					importance,
					groupName: group.name,
					kind: 'category',
					total: row.ytd.amount,
					monthly: cellsToMonthly(row.cells, months)
				});
			}
		} else {
			bars.push({
				name: group.name,
				importance,
				groupName: group.name,
				kind: 'group',
				total: group.subtotal.ytd.amount,
				monthly: cellsToMonthly(group.subtotal.cells, months)
			});
		}
	};

	for (const importance of report.importances) {
		for (const group of importance.groups) {
			pushGroup(group, importance.name);
		}
	}
	if (report.uncategorized) {
		pushGroup(report.uncategorized, '');
	}

	return { months, bars };
}

export { UNCATEGORIZED };

