1	<script lang="ts">
2		/**
3		 * Spending Report page
4		 *
5		 * Rolls a year's Expenses up through Category → Grouping → Area of Importance
6		 * and renders the month-by-month grid (subtotals per Grouping and Importance,
7		 * a Year-to-Date column, Uncategorized at the bottom, Grand Total).
8		 *
9		 * All aggregation is the pure `buildSpendingReport` — this page only loads the
10		 * data and paints the grid. Design: docs/plans/2026-07-09-spending-report-design.md
11		 */
12	
13		import { onMount } from 'svelte';
14		import { resolve } from '$app/paths';
15		import { goto } from '$app/navigation';
16		import { supabase } from '$lib/supabaseClient';
17		import { ExpenseService } from '$lib/services/ExpenseService';
18		import { CategoryService } from '$lib/services/CategoryService';
19		import { getDefaultFamilyId } from '$lib/utils/familyUtils';
20		import { formatCurrency } from '$lib/utils/formatCurrency';
21		import {
22			buildSpendingReport,
23			type SpendingReport,
24			type SpendingCategory,
25			type Cell,
26			type ReportRow
27		} from '$lib/utils/spendingReport';
28		import {
29			buildSpendingDrilldownParams,
30			type DrilldownScope,
31			type DrilldownColumn
32		} from '$lib/utils/spendingDrilldown';
33		import type { CategoryGroup } from '$lib/types/Hierarchy';
34		import SpendingChart from '$lib/components/SpendingChart.svelte';
35		import type { Session } from '@supabase/supabase-js';
36		import type { PageData } from './$types';
37	
38		let { data }: { data: PageData } = $props();
39	
40		let session: Session | null = $state(null);
41		let familyId: string | null = $state(null);
42		// The selected year comes from the `+page.ts` load (URL `?year=`). Load
43		// re-runs with the right URL on every navigation — arrows, Back, refresh — so
44		// this stays correct where the earlier client-side derivations went stale.
45		let year = $derived(data.year);
46		let view = $state<'table' | 'chart'>('table');
47		let loading = $state(true);
48		let error: string | null = $state(null);
49		let report = $state<SpendingReport | null>(null);
50		// Kept in state (not just local to loadReport) so cell drill-down can expand a
51		// Grouping/Importance to its member category ids.
52		let categories = $state<SpendingCategory[]>([]);
53		let groups = $state<CategoryGroup[]>([]);
54	
55		onMount(async () => {
56			const { data } = await supabase.auth.getSession();
57			session = data.session;
58			if (!session) {
59				loading = false;
60				return;
61			}
62	
63			familyId = await getDefaultFamilyId();
64			if (!familyId) {
65				error = 'No family found. Please contact support.';
66				loading = false;
67			}
68		});
69	
70		// Load (or reload) whenever the resolved family or the URL year changes. The
71		// URL is the source of truth for `year`, so a refresh / back-navigation to a
72		// past year reloads that year rather than the current one.
73		$effect(() => {
74			const reportYear = year; // track the derived year
75			if (session?.user && familyId) {
76				loadReport(reportYear);
77			}
78		});
79	
80		async function loadReport(reportYear: number) {
81			if (!session?.user || !familyId) return;
82	
83			try {
84				loading = true;
85				error = null;
86	
87				const categoryService = new CategoryService(supabase);
88				const expenseService = new ExpenseService(supabase);
89	
90				// Seed the default hierarchy the first time a family opens the report
91				// (idempotent server-side), mirroring how categories self-initialize.
92				let importanceAreas = await categoryService.getFamilyImportanceAreas(familyId);
93				if (importanceAreas.length === 0) {
94					await categoryService.createDefaultHierarchy(familyId);
95					importanceAreas = await categoryService.getFamilyImportanceAreas(familyId);
96				}
97	
98				const [loadedGroups, loadedCategories, expenses] = await Promise.all([
99					categoryService.getFamilyGroups(familyId),
100					categoryService.getFamilyCategories(familyId),
101					expenseService.getExpenses(session.user.id, {
102						startDate: `${reportYear}-01-01`,
103						endDate: `${reportYear}-12-31`
104					})
105				]);
106	
107				groups = loadedGroups;
108				categories = loadedCategories;
109				report = buildSpendingReport(
110					expenses,
111					loadedCategories,
112					loadedGroups,
113					importanceAreas,
114					reportYear
115				);
116			} catch (err) {
117				console.error('Error loading spending report:', err);
118				error = err instanceof Error ? err.message : 'Failed to load the spending report';
119			} finally {
120				loading = false;
121			}
122		}
123	
124		function changeYear(delta: number) {
125			// Navigate to the new year in the URL; `load` re-runs, `data.year` updates,
126			// and the reload effect follows. replaceState keeps the back-stack clean so
127			// Back returns to wherever the user came from, not each year they stepped
128			// through. keepFocus/noScroll avoid the arrow losing focus / a scroll jump.
129			goto(resolve(`/spending?year=${year + delta}`), {
130				replaceState: true,
131				keepFocus: true,
132				noScroll: true
133			});
134		}
135	
136		/** A cell renders blank when no receipts fell in it, otherwise the amount. */
137		function cellText(cell: Cell): string {
138			return cell.count === 0 ? '' : formatCurrency(cell.amount);
139		}
140	
141		/**
142		 * The drill-down scope for a detail row: a real category when the row maps to
143		 * one (including a named-but-ungrouped Uncategorized row), otherwise the
144		 * "(No category)" catch-all drills to the uncategorized Expenses filter.
145		 */
146		function rowScope(row: ReportRow): DrilldownScope {
147			return row.categoryId
148				? { kind: 'category', categoryId: row.categoryId }
149				: { kind: 'uncategorized' };
150		}
151	
152		/**
153		 * The Expenses-view query a clicked cell links to, filtered to exactly what it
154		 * sums. Returns just the query string; the template builds the `/expenses?…`
155		 * template literal and wraps it in `resolve()` (both SvelteKit's typed `resolve`
156		 * and the no-navigation-without-resolve lint rule want that at the call site).
157		 */
158		function drilldownQuery(scope: DrilldownScope, column: DrilldownColumn): string {
159			return buildSpendingDrilldownParams(scope, column, year, categories, groups).toString();
160		}
161	
162		const hasData = $derived(report !== null && report.months.length > 0);
163	</script>
164	
165	<svelte:head>
166		<title>Spending — YFL Expense Tracker</title>
167	</svelte:head>
168	
169	<div class="spending-page">
170		<div class="mb-6 flex flex-wrap items-center justify-between gap-3">
171			<div>
172				<h1 class="mb-2 text-2xl font-bold">Spending</h1>
173				<p class="text-gray-600">
174					Your expenses by Area of Importance, Grouping, and Category. Amounts in CAD.
175				</p>
176			</div>
177			<div class="flex items-center gap-4">
178				<a
179					href={resolve('/spending/hierarchy')}
180					class="rounded border border-gray-300 px-3 py-1 text-sm hover:bg-gray-100"
181				>
182					Edit hierarchy
183				</a>
184				<div class="inline-flex overflow-hidden rounded border border-gray-300" role="group">
185					<button
186						type="button"
187						class="px-3 py-1 text-sm {view === 'table'
188							? 'bg-indigo-600 text-white'
189							: 'bg-white text-gray-700 hover:bg-gray-100'}"
190						aria-pressed={view === 'table'}
191						onclick={() => (view = 'table')}
192					>
193						Table
194					</button>
195					<button
196						type="button"
197						class="border-l border-gray-300 px-3 py-1 text-sm {view === 'chart'
198							? 'bg-indigo-600 text-white'
199							: 'bg-white text-gray-700 hover:bg-gray-100'}"
200						aria-pressed={view === 'chart'}
201						onclick={() => (view = 'chart')}
202					>
203						Chart
204					</button>
205				</div>
206				<div class="flex items-center gap-2">
207					<button
208						type="button"
209						class="rounded border border-gray-300 px-3 py-1 text-sm hover:bg-gray-100"
210						onclick={() => changeYear(-1)}
211						aria-label="Previous year"
212					>
213						←
214					</button>
215					<span class="min-w-16 text-center text-lg font-semibold" aria-live="polite">{year}</span>
216					<button
217						type="button"
218						class="rounded border border-gray-300 px-3 py-1 text-sm hover:bg-gray-100"
219						onclick={() => changeYear(1)}
220						aria-label="Next year"
221					>
222						→
223					</button>
224				</div>
225			</div>
226		</div>
227	
228		{#if loading}
229			<div class="flex items-center justify-center p-8 text-gray-500">Loading spending report…</div>
230		{:else if error}
231			<div class="rounded border border-red-200 bg-red-50 p-4 text-red-700">{error}</div>
232		{:else if !hasData}
233			<div class="rounded border border-gray-200 bg-gray-50 p-8 text-center text-gray-500">
234				No expenses recorded for {year}.
235			</div>
236		{:else if report}
237			{#if report.missingAmountCount > 0}
238				<p class="mb-3 text-sm text-yellow-700">
239					⚠ {report.missingAmountCount} receipt{report.missingAmountCount === 1 ? '' : 's'} in {year}
240					{report.missingAmountCount === 1 ? 'has' : 'have'} no amount and count as $0. Open them on the
241					Receipts page to fix.
242				</p>
243			{/if}
244	
245			{#snippet nameCell(name: string, scope: DrilldownScope)}
246				<!--
247					A row's label links to every Expense the row rolls up for the year (its
248					Year-to-Date column), so the whole row — not just each month cell — is
249					clickable. Long names truncate to one line; the full name shows on hover.
250				-->
251				<a
252					class="block max-w-64 truncate hover:text-indigo-600 hover:underline"
253					href={resolve(`/expenses?${drilldownQuery(scope, { kind: 'ytd' })}`)}
254					title={name}>{name}</a
255				>
256			{/snippet}
257	
258			{#snippet valueCells(row: ReportRow, scope: DrilldownScope)}
259				{#each row.cells as cell, i (cell)}
260					<td class="px-3 py-1 text-right tabular-nums">
261						{#if cell.count > 0}
262							<!-- months run Jan → maxMonth contiguously, so column i is month i+1 -->
263							<a
264								class="hover:text-indigo-600 hover:underline"
265								href={resolve(`/expenses?${drilldownQuery(scope, { kind: 'month', month: i + 1 })}`)}
266								title="View these expenses">{cellText(cell)}</a
267							>
268						{/if}
269					</td>
270				{/each}
271				<td class="px-3 py-1 text-right font-semibold tabular-nums">
272					{#if row.ytd.count > 0}
273						<a
