297										>
298									</th>
299								{/each}
300								<th class="px-3 py-2 text-right font-semibold">
301									<a
302										class="hover:text-indigo-600 hover:underline"
303										href={resolve(
304											`/expenses?${drilldownQuery({ kind: 'grandTotal' }, { kind: 'ytd' })}`
305										)}
306										title="View all expenses for {year}">Year to Date</a
307									>
308								</th>
309							</tr>
