364												`/expenses?${drilldownQuery({ kind: 'uncategorized' }, { kind: 'ytd' })}`
365											)}
366											title="View all Uncategorized expenses for {year}">Uncategorized</a
367										>
368									</td>
369								</tr>
370								{#each report.uncategorized.rows as row (row.name)}
371									<tr class="border-b border-gray-100">
372										<td class="px-3 py-1 pl-8">{@render nameCell(row.name, rowScope(row))}</td>
373										{@render valueCells(row, rowScope(row))}
374									</tr>
375								{/each}
376								<tr class="border-b-2 border-amber-200 bg-amber-50 font-semibold">
377									<td class="px-3 py-1"
378										>{@render nameCell('Uncategorized Total', { kind: 'uncategorized' })}</td
379									>
380									{@render valueCells(report.uncategorized.subtotal, { kind: 'uncategorized' })}
381								</tr>
382							{/if}
383	
384							<tr class="border-t-2 border-gray-400 bg-gray-200 font-bold">
385								<td class="px-3 py-2">{@render nameCell('Grand Total', { kind: 'grandTotal' })}</td>
386								{@render valueCells(report.grandTotal, { kind: 'grandTotal' })}
387							</tr>
388						</tbody>
389					</table>
390				</div>
391			{:else}
392				<SpendingChart {report} />
393			{/if}
394		{/if}
395	</div>
