1	<script lang="ts">
2		/**
3		 * SpendingChart — an accordion magnitude bar chart of the Spending Report.
4		 *
5		 * One solid bar per Grouping = its year-to-date total, coloured by Area of
6		 * Importance. Each Grouping can be **expanded in place** (via its ± bracket) to
7		 * reveal its Category bars while siblings stay visible; any number can be open
8		 * at once. Two bracket rows under the axis carry the hierarchy: a per-Grouping
9		 * toggle row, then the Area-of-Importance row. Every bar carries a value label
10		 * so small bars stay readable next to a dominant one.
11		 *
12		 * (Month-by-month detail lives in the Table view and the future trend chart.)
13		 *
14		 * Built on LayerChart's <BarChart>; data shaping is the pure `buildSpendingChart`.
15		 * Design: docs/plans/2026-07-09-spending-report-design.md
16		 */
17		import { BarChart, Text } from 'layerchart';
18		import type { ChartState } from 'layerchart';
19		import { SvelteSet } from 'svelte/reactivity';
20		import { buildSpendingChart, type ChartBar } from '$lib/utils/spendingChart';
21		import type { SpendingReport } from '$lib/utils/spendingReport';
22		import { formatCurrency } from '$lib/utils/formatCurrency';
23	
24		let { report }: { report: SpendingReport } = $props();
25	
26		// Grouping names currently expanded to their Categories (accordion; many at once).
27		const expandedGroups = new SvelteSet<string>();
28	
29		const model = $derived(buildSpendingChart(report, expandedGroups));
30	
31		function toggleGroup(name: string) {
32			if (expandedGroups.has(name)) expandedGroups.delete(name);
33			else expandedGroups.add(name);
34		}
35	
36		// LayerChart data: a stable unique id per bar (names can repeat across groups,
37		// which would collide on the band scale), plus the fields the chart reads.
38		const data = $derived(
39			model.bars.map((bar, i) => ({
40				id: `b${i}`,
41				name: bar.name,
42				kind: bar.kind,
43				importance: bar.importance,
44				total: bar.total
45			}))
46		);
47	
48		// Validated categorical palette (dataviz), assigned to Importances in report
49		// order; the no-importance (Uncategorized) bars get a neutral gray.
50		const IMPORTANCE_PALETTE = ['#4f46e5', '#0d9488', '#d97706', '#7c3aed', '#db2777'];
51		const NEUTRAL = '#9ca3af';
52	
53		const importanceColors = $derived.by(() => {
54			const domain: string[] = [];
55			const range: string[] = [];
56			let next = 0;
57			for (const bar of model.bars) {
58				if (domain.includes(bar.importance)) continue;
59				domain.push(bar.importance);
60				if (bar.importance === '') {
61					range.push(NEUTRAL);
62				} else {
63					range.push(IMPORTANCE_PALETTE[next % IMPORTANCE_PALETTE.length]);
64					next++;
65				}
66			}
67			return { domain, range };
68		});
69	
70		const cDomain = $derived(importanceColors.domain);
71		const cRange = $derived(importanceColors.range);
72	
73		function importanceColor(name: string): string {
74			const idx = importanceColors.domain.indexOf(name);
75			return idx >= 0 ? importanceColors.range[idx] : NEUTRAL;
76		}
77	
78		// Bound LayerChart state; its scales position the brackets, labels, and toggles.
79		let chartContext = $state<ChartState | undefined>(undefined);
80	
81		/** The x-scale is a band scale for categorical bars; AnyScale hides bandwidth. */
82		interface BandScale {
83			(value: string): number | undefined;
84			bandwidth(): number;
85		}
86		type LinearScale = (value: number) => number;
87	
88		function bandScale(): BandScale | null {
89			const xScale = chartContext?.xScale as unknown as BandScale | undefined;
90			return xScale && typeof xScale.bandwidth === 'function' ? xScale : null;
91		}
92	
93		// Truncate a tick label to what fits one bar width (~6.5px per char at the tick
94		// font size); the full name is always available in the hover tooltip.
95		function fitLabel(name: string): string {
96			const bandwidth = bandScale()?.bandwidth() ?? 0;
97			const maxChars = Math.max(3, Math.floor(bandwidth / 6.5));
98			return name.length > maxChars ? `${name.slice(0, maxChars - 1).trimEnd()}…` : name;
99		}
100	
101		interface Span {
102			key: string;
103			left: number;
104			width: number;
105		}
106	
107		/** Pixel span of bars [start..end] (inclusive) from the band scale, or null. */
108		function spanOf(start: number, end: number): Omit<Span, 'key'> | null {
109			const ctx = chartContext;
110			const xScale = bandScale();
111			if (!ctx || !xScale) return null;
112			const a = xScale(`b${start}`);
113			const b = xScale(`b${end}`);
114			if (typeof a !== 'number' || typeof b !== 'number') return null;
115			return { left: ctx.padding.left + a, width: b + xScale.bandwidth() - a };
116		}
117	
118		interface GroupBracket extends Span {
119			groupName: string;
120			importance: string;
121			expanded: boolean;
122		}
123	
124		// One toggle bracket per Grouping, spanning its bar(s) — collapsed (1 bar) or
125		// expanded (its category bars).
126		const groupBrackets = $derived.by((): GroupBracket[] => {
127			if (!bandScale()) return [];
128			const out: GroupBracket[] = [];
129			let i = 0;
130			while (i < model.bars.length) {
131				const g = model.bars[i].groupName;
132				let j = i;
133				while (j + 1 < model.bars.length && model.bars[j + 1].groupName === g) j++;
134				const span = spanOf(i, j);
135				if (span) {
136					out.push({
137						...span,
138						key: g,
139						groupName: g,
140						importance: model.bars[i].importance,
141						expanded: expandedGroups.has(g)
142					});
143				}
144				i = j + 1;
145			}
146			return out;
147		});
148	
149		interface ImportanceBracket extends Span {
150			name: string;
151			color: string;
152		}
153	
154		// One bracket per contiguous run of same-Importance bars (skips Uncategorized).
155		const importanceBrackets = $derived.by((): ImportanceBracket[] => {
156			if (!bandScale()) return [];
157			const out: ImportanceBracket[] = [];
158			let i = 0;
159			while (i < model.bars.length) {
160				const imp = model.bars[i].importance;
161				let j = i;
162				while (j + 1 < model.bars.length && model.bars[j + 1].importance === imp) j++;
163				if (imp !== '') {
164					const span = spanOf(i, j);
165					if (span) out.push({ ...span, key: `${imp}-${i}`, name: imp, color: importanceColor(imp) });
166				}
167				i = j + 1;
168			}
169			return out;
170		});
171	
172		interface ValueLabel {
173			cx: number;
174			top: number;
175			text: string;
176			key: string;
177		}
178	
179		// A currency label above each bar top; readable even when one bar dominates.
180		const valueLabels = $derived.by((): ValueLabel[] => {
181			const ctx = chartContext;
182			const xScale = bandScale();
183			const yScale = ctx?.yScale as unknown as LinearScale | undefined;
184			if (!ctx || !xScale || typeof yScale !== 'function') return [];
185			const bandwidth = xScale.bandwidth();
186			const labels: ValueLabel[] = [];
187			model.bars.forEach((bar, i) => {
188				const x = xScale(`b${i}`);
189				const y = yScale(bar.total);
190				if (typeof x !== 'number' || typeof y !== 'number') return;
191				labels.push({
192					cx: ctx.padding.left + x + bandwidth / 2,
193					top: ctx.padding.top + y,
194					text: formatCurrency(bar.total),
195					key: `b${i}`
196				});
197			});
198			return labels;
199		});
200	
201		interface BarTarget {
202			key: string;
203			left: number;
204			width: number;
205			top: number;
206			height: number;
207			bar: ChartBar;
208		}
209	
210		// A transparent full-height column over each bar handling both click (toggle
211		// its Grouping) and hover (custom tooltip). These are mouse affordances —
212		// aria-hidden, non-focusable — the ± brackets are the accessible controls.
213		const barTargets = $derived.by((): BarTarget[] => {
214			const ctx = chartContext;
215			const xScale = bandScale();
216			if (!ctx || !xScale) return [];
217			const bandwidth = xScale.bandwidth();
218			const out: BarTarget[] = [];
219			model.bars.forEach((bar, i) => {
220				const x = xScale(`b${i}`);
221				if (typeof x !== 'number') return;
222				out.push({
223					key: `b${i}`,
224					left: ctx.padding.left + x,
225					width: bandwidth,
226					top: ctx.padding.top,
227					height: ctx.height,
228					bar
229				});
230			});
231			return out;
232		});
233	
234		// Hover tooltip state, positioned relative to the chart wrapper.
235		let chartWrapper = $state<HTMLDivElement>();
236		let hovered = $state<{ bar: ChartBar; x: number; y: number } | null>(null);
237	
238		function pointerPos(event: PointerEvent): { x: number; y: number } {
239			const rect = chartWrapper?.getBoundingClientRect();
240			return rect ? { x: event.clientX - rect.left, y: event.clientY - rect.top } : { x: 0, y: 0 };
241		}
242	</script>
243	
244	<div class="flex flex-col gap-2">
245		{#if model.bars.length === 0}
246			<div class="rounded border border-gray-200 bg-gray-50 p-8 text-center text-gray-500">
247				Nothing to chart for this selection.
248			</div>
249		{:else}
250			<div class="relative w-full" bind:this={chartWrapper}>
251				<div class="relative h-[28rem] w-full">
252					<BarChart
253						bind:context={chartContext}
254						{data}
255						x="id"
256						y="total"
257						c="importance"
258						{cDomain}
259						{cRange}
260						bandPadding={0.2}
261						legend={false}
262						tooltipContext={false}
263						props={{
264							xAxis: { tickLabel: xTickLabel },
265							yAxis: { format: (v: number) => formatCurrency(v) }
266						}}
267					/>
268	
269					<!-- Transparent per-bar layer: click toggles the Grouping, hover shows the tooltip. -->
270					{#if barTargets.length > 0}
271						<div class="absolute inset-0">
272							{#each barTargets as target (target.key)}
273								<button
274									type="button"
275									aria-hidden="true"
276									tabindex="-1"
277									data-group={target.bar.groupName}
278									class="absolute cursor-pointer"
279									style="left: {target.left}px; top: {target.top}px; width: {target.width}px; height: {target.height}px"
280									onpointerenter={(e) => (hovered = { bar: target.bar, ...pointerPos(e) })}
281									onpointermove={(e) => {
282										if (hovered) hovered = { bar: target.bar, ...pointerPos(e) };
283									}}
284									onpointerleave={() => (hovered = null)}
285									onclick={() => {
286										toggleGroup(target.bar.groupName);
287										hovered = null;
288									}}
289								></button>
290							{/each}
291						</div>
292					{/if}
293	
294					<!-- x tick: Category name for expanded bars; group bars are named by their bracket. -->
295					{#snippet xTickLabel({ props, index }: { props: Record<string, unknown>; index: number })}
296						{@const bar = data[index]}
297						<Text {...props} value={bar?.kind === 'category' ? fitLabel(bar.name) : ''} />
298					{/snippet}
299	
300					<!-- Value label above each bar top. -->
301					{#if valueLabels.length > 0}
302						<div class="pointer-events-none absolute inset-0" aria-hidden="true">
303							{#each valueLabels as label (label.key)}
304								<div
305									class="absolute -translate-x-1/2 -translate-y-full pb-0.5 text-[10px] font-medium whitespace-nowrap text-gray-700"
306									style="left: {label.cx}px; top: {label.top}px"
307								>
308									{label.text}
309								</div>
310							{/each}
311						</div>
312					{/if}
313				</div>
314	
315				<!-- Row 1: per-Grouping ± toggle brackets (expand/collapse in place). -->
316				{#if groupBrackets.length > 0}
317					<div class="relative mt-1 h-6">
318						{#each groupBrackets as bracket (bracket.key)}
319							<button
320								type="button"
321								class="absolute top-0 truncate rounded-sm border-t-2 border-gray-300 pt-0.5 text-center text-xs font-medium text-gray-600 hover:bg-gray-100 hover:text-gray-900"
322								style="left: {bracket.left}px; width: {bracket.width}px"
323								aria-expanded={bracket.expanded}
324								aria-label={`${bracket.expanded ? 'Collapse' : 'Expand'} ${bracket.groupName}`}
325								onclick={() => toggleGroup(bracket.groupName)}
326							>
327								<span class="font-semibold">{bracket.expanded ? '−' : '+'}</span>
328								{bracket.groupName}
329							</button>
330						{/each}
331					</div>
332				{/if}
333	
334				<!-- Row 2: Area-of-Importance brackets, labelled once, coloured. -->
335				{#if importanceBrackets.length > 0}
336					<div class="relative mt-1 h-6" aria-hidden="true">
337						{#each importanceBrackets as bracket (bracket.key)}
338							<div class="absolute top-0" style="left: {bracket.left}px; width: {bracket.width}px">
339								<div
340									class="mx-1 border-t-2 pt-0.5 text-center text-xs font-semibold tracking-wide uppercase"
341									style="border-color: {bracket.color}; color: {bracket.color}"
342								>
343									{bracket.name}
344								</div>
345							</div>
346						{/each}
347					</div>
348				{/if}
349	
350				<!-- Hover tooltip: name, per-month totals, and the grand total. -->
351				{#if hovered}
352					<div
353						class="pointer-events-none absolute z-10 max-w-64 rounded bg-gray-900 px-2.5 py-2 text-xs text-white shadow-lg"
354						style="left: {hovered.x + 14}px; top: {hovered.y + 14}px"
355						role="tooltip"
356					>
357						<div class="font-semibold">{hovered.bar.name}</div>
358						<div class="text-[10px] tracking-wide text-gray-400 uppercase">
359							{hovered.bar.kind === 'group' ? 'Grouping' : 'Category'}{hovered.bar.importance
360								? ` · ${hovered.bar.importance}`
361								: ''}
362						</div>
363						<div class="mt-1.5 space-y-0.5">
364							{#each model.months as month (month)}
365								{#if hovered.bar.monthly[month]}
366									<div class="flex justify-between gap-6">
367										<span class="text-gray-400">{month}</span>
368										<span class="tabular-nums">{formatCurrency(hovered.bar.monthly[month])}</span>
369									</div>
370								{/if}
371							{/each}
372							<div
373								class="mt-1 flex justify-between gap-6 border-t border-white/20 pt-1 font-semibold"
374							>
375								<span>Total</span>
376								<span class="tabular-nums">{formatCurrency(hovered.bar.total)}</span>
377							</div>
378						</div>
379					</div>
380				{/if}
381			</div>
382	
383			<p class="text-sm text-gray-500">
384				Bar per Grouping — click a bar or its <span class="font-semibold">±</span> to expand it into its
385				categories; hover for the monthly breakdown.
386			</p>
387		{/if}
388	</div>
