/**
 * Shared currency formatting utility
 * #{#fcr5a} - Replaces inconsistent per-page formatting with a single approach
 *
 * Uses Intl.NumberFormat('en-CA') for locale-correct symbols:
 *   CAD → $25.99
 *   EUR → €45.00
 *   GBP → £30.00
 *   USD → US$25.99 (disambiguated from CAD $)
 */

// Intl.NumberFormat throws RangeError unless the currency is exactly 3 ASCII letters.
// Bad values in the DB (e.g. "$", "C", "CA") must not crash a page render — fall back to CAD.
function normalizeCurrencyCode(currency?: string | null): string {
	const upper = (currency ?? '').toUpperCase();
	return /^[A-Z]{3}$/.test(upper) ? upper : 'CAD';
}

/**
 * Format a monetary amount with the correct currency symbol.
 * Defaults to CAD when currency is null/omitted or not a well-formed 3-letter code.
 */
export function formatCurrency(
	amount: number | null | undefined,
	currency?: string | null
): string {
	if (amount === null || amount === undefined) return '—';

	return new Intl.NumberFormat('en-CA', {
		style: 'currency',
		currency: normalizeCurrencyCode(currency)
	}).format(amount);
}

/**
 * Format a foreign currency amount with an approximate CAD estimate.
 *
 * For foreign currency receipts: "€45.00 (≈$68.85)"
 * For CAD receipts or when no estimate is available: "$25.99"
 */
export function formatCurrencyWithEstimate(
	amount: number | null | undefined,
	currency?: string | null,
	convertedCAD?: number | null
): string {
	if (amount === null || amount === undefined) return '—';

	const formatted = formatCurrency(amount, currency);
	const isForeignCurrency = currency !== null && currency !== undefined && currency !== 'CAD';

	if (isForeignCurrency && convertedCAD !== null && convertedCAD !== undefined) {
		const cadFormatted = formatCurrency(convertedCAD, 'CAD');
		return `${formatted} (≈${cadFormatted})`;
	}

	return formatted;
}

