}

const mixed = [
	expense({ category_id: 'cat-groceries', total_amount: 40 }), // Essential/Everyday
	expense({ category_id: 'cat-clothes', total_amount: 25 }), // Essential/Everyday
	expense({ category_id: 'cat-utilities', total_amount: 200 }), // Essential/Home
	expense({ category_id: 'cat-allowance', total_amount: 10 }), // Priorities/Kids
	expense({ category_id: 'cat-orphan', total_amount: 60 }) // Uncategorized
];

describe('collapsed (nothing expanded)', () => {
	it('emits one group bar per grouping, ordered by importance then name', () => {
		const model = chart(mixed);
		expect(model.bars.map((b) => b.name)).toEqual(['Everyday', 'Home', 'Kids', 'Uncategorized']);
		expect(model.bars.every((b) => b.kind === 'group')).toBe(true);
		expect(model.bars.map((b) => b.importance)).toEqual([
			'Essential',
			'Essential',
			'Priorities',
			''
		]);
	});

