/**
 * Spending Waterfall / bridge model (pure)
 *
 * Reshapes the current-year and prior-year SpendingReports into a **horizontal
 * waterfall (bridge)**: a running total that starts at the prior-year same-period
 * grand total, steps up/down once per spending area, and lands on the current-year
 * grand total. Areas sit on the Y-axis (one row each); the X-axis is the running
 * cumulative amount.
 *
 * Unlike the magnitude chart (which reads only the current report), the bridge
 * must **reconcile** — start + Σ(all deltas) = end — so it walks the **union** of
 * groups/categories across both years. A group that spent last year but nothing
 * this year (no current row) shows up as its own downward step; that's the
 * "disappeared spend" the Change column and bar marker can't surface.
 *
 * The accordion is preserved: expanding a Grouping replaces its single step with
 * its Category steps in place, and because the category deltas sum to the group
 * delta, the running total on either side is unchanged.
 *
 * Parity: prior totals are summed over the current report's visible-month window
 * (whole months), matching `withPriorPeriod`. No I/O — unit-tested like the rest.
 *
 * Design: docs/plans/2026-07-09-spending-report-design.md
 */

import type { SpendingReport, GroupSection, ReportRow } from './spendingReport';

const NO_CATEGORY_ROW = '(No category)';
const UNCATEGORIZED = 'Uncategorized';

export type WaterfallKind = 'anchor-start' | 'step' | 'anchor-end';
export type WaterfallLevel = 'anchor' | 'group' | 'category';
export type ChangeDirection = 'up' | 'down' | 'flat';

/** One row of the bridge: a start/end anchor, or a floating step (group or category). */
export interface WaterfallRow {
	key: string;
	label: string;
	kind: WaterfallKind;
	level: WaterfallLevel;
	/** Area of Importance this row rolls up to; '' for Uncategorized and anchors. */
	importance: string;
	/** The Grouping this row belongs to — the unit of expand/collapse ('' for anchors). */
	groupName: string;
	/** Current-year total (the anchor's own total for anchors). */
	current: number;
	/** Prior-year same-period total. */
	prior: number;
	/** current − prior (0 for anchors). */
	delta: number;
	/** Running cumulative value where this row's bar starts / ends (anchors start at 0). */
	from: number;
	to: number;
	direction: ChangeDirection;
	/** A group step that can be expanded into category steps. */
	expandable: boolean;
	expanded: boolean;
}

export interface WaterfallModel {
	rows: WaterfallRow[];
	/** Min/max running value across every bar (plus 0), for the X-axis domain. */
	domainMin: number;
	domainMax: number;
	year: number;
	priorYear: number;
}

/** Sum a prior row's cells over the first `window` months (parity truncation). */
function windowSum(row: ReportRow, window: number): number {
	let total = 0;
	const upto = Math.min(window, row.cells.length);
	for (let i = 0; i < upto; i++) total += row.cells[i].amount;
	return total;
}

function directionOf(delta: number): ChangeDirection {
	return delta > 0 ? 'up' : delta < 0 ? 'down' : 'flat';
}

/** Case-insensitive name sort with "(No category)" pinned last (mirrors the report). */
function byName(a: string, b: string): number {
	if (a === NO_CATEGORY_ROW) return 1;
	if (b === NO_CATEGORY_ROW) return -1;
	return a.localeCompare(b, undefined, { sensitivity: 'base' });
}

interface CategoryMovement {
	key: string;
	label: string;
	current: number;
	prior: number;
}

/**
 * Union of the categories under a group across both years, matched by category id
 * (the "(No category)" row by name). Current-only categories get prior 0;
 * prior-only categories get current 0. Deltas sum to the group's delta.
 */
function unionCategories(
	cur: GroupSection | undefined,
	pri: GroupSection | undefined,
	window: number
): CategoryMovement[] {
	const byKey = new Map<string, CategoryMovement>();
	const keyOf = (row: ReportRow) => row.categoryId ?? `name:${row.name}`;

	for (const row of cur?.rows ?? []) {
		byKey.set(keyOf(row), { key: keyOf(row), label: row.name, current: row.ytd.amount, prior: 0 });
	}
	for (const row of pri?.rows ?? []) {
		const k = keyOf(row);
		const existing = byKey.get(k);
		const prior = windowSum(row, window);
		if (existing) existing.prior = prior;
		else byKey.set(k, { key: k, label: row.name, current: 0, prior });
	}

	return [...byKey.values()].sort((a, b) => byName(a.label, b.label));
}

interface GroupMovement {
	groupName: string;
	importance: string;
	importanceSort: number;
	cur?: GroupSection;
	pri?: GroupSection;
	current: number;
	prior: number;
}

/**
 * Build the bridge for a current/prior report pair and the current expand state.
 *
 * @param current        The selected year's report.
 * @param prior          The prior year's report (its cells are truncated to the
 *                       current report's month window for parity).
 * @param expandedGroups Grouping names currently expanded to their Categories.
 */
export function buildWaterfallBridge(
	current: SpendingReport,
	prior: SpendingReport,
	expandedGroups: ReadonlySet<string>
): WaterfallModel {
	const year = current.year;
	const priorYear = prior.year;
	const window = current.months.length;

	if (window === 0) {
		return { rows: [], domainMin: 0, domainMax: 0, year, priorYear };
	}

	// --- collect group movements in Importance → group-name order, union of years -
	const impMeta = new Map<string, { name: string; sort: number }>();
	for (const imp of current.importances) impMeta.set(imp.id, { name: imp.name, sort: imp.sortOrder });
	for (const imp of prior.importances) {
		if (!impMeta.has(imp.id)) impMeta.set(imp.id, { name: imp.name, sort: imp.sortOrder });
	}
	const curImpById = new Map(current.importances.map((i) => [i.id, i]));
	const priImpById = new Map(prior.importances.map((i) => [i.id, i]));

	const orderedImpIds = [...impMeta.keys()].sort((a, b) => {
		const A = impMeta.get(a)!;
		const B = impMeta.get(b)!;
		return A.sort - B.sort || A.name.localeCompare(B.name);
	});

	const movements: GroupMovement[] = [];

	for (const impId of orderedImpIds) {
		const meta = impMeta.get(impId)!;
		const groupByName = new Map<string, { cur?: GroupSection; pri?: GroupSection }>();
		for (const g of curImpById.get(impId)?.groups ?? []) {
			groupByName.set(g.name, { cur: g });
		}
		for (const g of priImpById.get(impId)?.groups ?? []) {
			const existing = groupByName.get(g.name);
			if (existing) existing.pri = g;
			else groupByName.set(g.name, { pri: g });
		}

		const names = [...groupByName.keys()].sort((a, b) => byName(a, b));
		for (const name of names) {
			const { cur, pri } = groupByName.get(name)!;
			movements.push({
				groupName: name,
				importance: meta.name,
				importanceSort: meta.sort,
				cur,
				pri,
				current: cur?.subtotal.ytd.amount ?? 0,
				prior: pri ? windowSum(pri.subtotal, window) : 0
			});
		}
	}

	// Uncategorized trails, as a single synthetic group (no Importance).
	if (current.uncategorized || prior.uncategorized) {
		movements.push({
			groupName: UNCATEGORIZED,
			importance: '',
			importanceSort: Number.POSITIVE_INFINITY,
			cur: current.uncategorized ?? undefined,
			pri: prior.uncategorized ?? undefined,
			current: current.uncategorized?.subtotal.ytd.amount ?? 0,
			prior: prior.uncategorized ? windowSum(prior.uncategorized.subtotal, window) : 0
		});
	}

	// --- lay out the running total: start anchor → steps → end anchor ------------
	const priorGrand = windowSum(prior.grandTotal, window);
	const currentGrand = current.grandTotal.ytd.amount;

	const rows: WaterfallRow[] = [];
	const running0 = 0;

	rows.push({
		key: 'anchor-start',
		label: String(priorYear),
		kind: 'anchor-start',
		level: 'anchor',
		importance: '',
		groupName: '',
		current: priorGrand,
		prior: priorGrand,
		delta: 0,
		from: running0,
		to: priorGrand,
		direction: 'flat',
		expandable: false,
		expanded: false
	});

	let running = priorGrand;
	const pushStep = (
		label: string,
		level: WaterfallLevel,
		importance: string,
		groupName: string,
		key: string,
		curVal: number,
		priVal: number,
		expandable: boolean,
		expanded: boolean
	) => {
		const delta = curVal - priVal;
		const from = running;
		running += delta;
		rows.push({
			key,
			label,
			kind: 'step',
			level,
			importance,
			groupName,
			current: curVal,
			prior: priVal,
			delta,
			from,
			to: running,
			direction: directionOf(delta),
			expandable,
			expanded
		});
	};

	for (const mov of movements) {
		const cats = unionCategories(mov.cur, mov.pri, window);
		const expanded = expandedGroups.has(mov.groupName);
		if (expanded && cats.length > 0) {
			for (const cat of cats) {
				pushStep(
					cat.label,
					'category',
					mov.importance,
					mov.groupName,
					`cat:${mov.groupName}:${cat.key}`,
					cat.current,
					cat.prior,
					false,
					true
				);
			}
		} else {
			pushStep(
				mov.groupName,
				'group',
				mov.importance,
				mov.groupName,
				`grp:${mov.groupName}`,
				mov.current,
				mov.prior,
				cats.length > 0,
				false
			);
		}
	}

	rows.push({
		key: 'anchor-end',
		label: String(year),
		kind: 'anchor-end',
		level: 'anchor',
		importance: '',
		groupName: '',
		current: currentGrand,
		prior: currentGrand,
		delta: 0,
		from: running0,
		to: currentGrand,
		direction: 'flat',
		expandable: false,
		expanded: false
	});

	// --- X-axis domain: every bar edge, plus the baseline at 0 -------------------
	let domainMin = 0;
	let domainMax = 0;
	for (const row of rows) {
		domainMin = Math.min(domainMin, row.from, row.to);
		domainMax = Math.max(domainMax, row.from, row.to);
	}

	return { rows, domainMin, domainMax, year, priorYear };
}

