1	/**
2	 * Spending Waterfall / bridge model (pure)
3	 *
4	 * Reshapes the current-year and prior-year SpendingReports into a **horizontal
5	 * waterfall (bridge)**: a running total that starts at the prior-year same-period
6	 * grand total, steps up/down once per spending area, and lands on the current-year
7	 * grand total. Areas sit on the Y-axis (one row each); the X-axis is the running
8	 * cumulative amount.
9	 *
10	 * Unlike the magnitude chart (which reads only the current report), the bridge
11	 * must **reconcile** — start + Σ(all deltas) = end — so it walks the **union** of
12	 * groups/categories across both years. A group that spent last year but nothing
13	 * this year (no current row) shows up as its own downward step; that's the
14	 * "disappeared spend" the Change column and bar marker can't surface.
15	 *
16	 * The accordion is preserved: expanding a Grouping replaces its single step with
17	 * its Category steps in place, and because the category deltas sum to the group
18	 * delta, the running total on either side is unchanged.
19	 *
20	 * Parity: prior totals are summed over the current report's visible-month window
21	 * (whole months), matching `withPriorPeriod`. No I/O — unit-tested like the rest.
22	 *
23	 * Design: docs/plans/2026-07-09-spending-report-design.md
24	 */
25	
26	import type { SpendingReport, GroupSection, ReportRow } from './spendingReport';
27	
28	const NO_CATEGORY_ROW = '(No category)';
29	const UNCATEGORIZED = 'Uncategorized';
30	
31	export type WaterfallKind = 'anchor-start' | 'step' | 'group-header' | 'anchor-end';
32	export type WaterfallLevel = 'anchor' | 'group' | 'category';
33	export type ChangeDirection = 'up' | 'down' | 'flat';
34	
35	/** One row of the bridge: a start/end anchor, or a floating step (group or category). */
36	export interface WaterfallRow {
37		key: string;
38		label: string;
39		kind: WaterfallKind;
40		level: WaterfallLevel;
41		/** Area of Importance this row rolls up to; '' for Uncategorized and anchors. */
42		importance: string;
43		/** The Grouping this row belongs to — the unit of expand/collapse ('' for anchors). */
44		groupName: string;
45		/** Current-year total (the anchor's own total for anchors). */
46		current: number;
47		/** Prior-year same-period total. */
48		prior: number;
49		/** current − prior (0 for anchors). */
50		delta: number;
51		/** Running cumulative value where this row's bar starts / ends (anchors start at 0). */
52		from: number;
53		to: number;
54		direction: ChangeDirection;
55		/** A group step that can be expanded into category steps. */
56		expandable: boolean;
57		expanded: boolean;
58	}
59	
60	export interface WaterfallModel {
61		rows: WaterfallRow[];
62		/** Min/max running value across every bar (plus 0), for the X-axis domain. */
63		domainMin: number;
64		domainMax: number;
65		year: number;
66		priorYear: number;
67	}
68	
69	/** Sum a prior row's cells over the first `window` months (parity truncation). */
70	function windowSum(row: ReportRow, window: number): number {
71		let total = 0;
72		const upto = Math.min(window, row.cells.length);
73		for (let i = 0; i < upto; i++) total += row.cells[i].amount;
74		return total;
75	}
76	
77	function directionOf(delta: number): ChangeDirection {
78		return delta > 0 ? 'up' : delta < 0 ? 'down' : 'flat';
79	}
80	
81	/** Case-insensitive name sort with "(No category)" pinned last (mirrors the report). */
82	function byName(a: string, b: string): number {
83		if (a === NO_CATEGORY_ROW) return 1;
84		if (b === NO_CATEGORY_ROW) return -1;
85		return a.localeCompare(b, undefined, { sensitivity: 'base' });
86	}
87	
88	interface CategoryMovement {
89		key: string;
90		label: string;
91		current: number;
92		prior: number;
93	}
94	
95	/**
96	 * Union of the categories under a group across both years, matched by category id
97	 * (the "(No category)" row by name). Current-only categories get prior 0;
98	 * prior-only categories get current 0. Deltas sum to the group's delta.
99	 */
100	function unionCategories(
101		cur: GroupSection | undefined,
102		pri: GroupSection | undefined,
103		window: number
104	): CategoryMovement[] {
105		const byKey = new Map<string, CategoryMovement>();
106		const keyOf = (row: ReportRow) => row.categoryId ?? `name:${row.name}`;
107	
108		for (const row of cur?.rows ?? []) {
109			byKey.set(keyOf(row), { key: keyOf(row), label: row.name, current: row.ytd.amount, prior: 0 });
110		}
111		for (const row of pri?.rows ?? []) {
112			const k = keyOf(row);
113			const existing = byKey.get(k);
114			const prior = windowSum(row, window);
115			if (existing) existing.prior = prior;
116			else byKey.set(k, { key: k, label: row.name, current: 0, prior });
117		}
118	
119		return [...byKey.values()].sort((a, b) => byName(a.label, b.label));
120	}
121	
122	interface GroupMovement {
123		groupName: string;
124		importance: string;
125		importanceSort: number;
126		cur?: GroupSection;
127		pri?: GroupSection;
128		current: number;
129		prior: number;
130	}
131	
132	/**
133	 * Build the bridge for a current/prior report pair and the current expand state.
134	 *
135	 * @param current        The selected year's report.
136	 * @param prior          The prior year's report (its cells are truncated to the
137	 *                       current report's month window for parity).
138	 * @param expandedGroups Grouping names currently expanded to their Categories.
139	 */
140	export function buildWaterfallBridge(
141		current: SpendingReport,
142		prior: SpendingReport,
143		expandedGroups: ReadonlySet<string>
144	): WaterfallModel {
145		const year = current.year;
146		const priorYear = prior.year;
147		const window = current.months.length;
148	
149		if (window === 0) {
150			return { rows: [], domainMin: 0, domainMax: 0, year, priorYear };
151		}
152	
153		// --- collect group movements in Importance → group-name order, union of years -
154		const impMeta = new Map<string, { name: string; sort: number }>();
155		for (const imp of current.importances)
156			impMeta.set(imp.id, { name: imp.name, sort: imp.sortOrder });
157		for (const imp of prior.importances) {
158			if (!impMeta.has(imp.id)) impMeta.set(imp.id, { name: imp.name, sort: imp.sortOrder });
159		}
160		const curImpById = new Map(current.importances.map((i) => [i.id, i]));
161		const priImpById = new Map(prior.importances.map((i) => [i.id, i]));
162	
163		const orderedImpIds = [...impMeta.keys()].sort((a, b) => {
164			const A = impMeta.get(a)!;
165			const B = impMeta.get(b)!;
166			return A.sort - B.sort || A.name.localeCompare(B.name);
167		});
168	
169		const movements: GroupMovement[] = [];
170	
171		for (const impId of orderedImpIds) {
172			const meta = impMeta.get(impId)!;
173			const groupByName = new Map<string, { cur?: GroupSection; pri?: GroupSection }>();
174			for (const g of curImpById.get(impId)?.groups ?? []) {
175				groupByName.set(g.name, { cur: g });
176			}
177			for (const g of priImpById.get(impId)?.groups ?? []) {
178				const existing = groupByName.get(g.name);
179				if (existing) existing.pri = g;
180				else groupByName.set(g.name, { pri: g });
181			}
182	
183			const names = [...groupByName.keys()].sort((a, b) => byName(a, b));
184			for (const name of names) {
185				const { cur, pri } = groupByName.get(name)!;
186				movements.push({
187					groupName: name,
188					importance: meta.name,
189					importanceSort: meta.sort,
190					cur,
191					pri,
192					current: cur?.subtotal.ytd.amount ?? 0,
193					prior: pri ? windowSum(pri.subtotal, window) : 0
194				});
195			}
196		}
197	
198		// Uncategorized trails, as a single synthetic group (no Importance).
199		if (current.uncategorized || prior.uncategorized) {
200			movements.push({
201				groupName: UNCATEGORIZED,
202				importance: '',
203				importanceSort: Number.POSITIVE_INFINITY,
204				cur: current.uncategorized ?? undefined,
205				pri: prior.uncategorized ?? undefined,
206				current: current.uncategorized?.subtotal.ytd.amount ?? 0,
207				prior: prior.uncategorized ? windowSum(prior.uncategorized.subtotal, window) : 0
208			});
209		}
