	// --- X-axis domain: the running-total band, NOT anchored at 0 ----------------
	// Steps' from/to trace the band (incl. the intermediate peak/trough); anchors
	// contribute only their total (`to`) — their `from` is the off-scale 0 we omit.
	let lo = Number.POSITIVE_INFINITY;
	let hi = Number.NEGATIVE_INFINITY;
	for (const row of rows) {
		const edges = row.level === 'anchor' ? [row.to] : [row.from, row.to];
		for (const v of edges) {
			if (v < lo) lo = v;
			if (v > hi) hi = v;
		}
	}
	const rawSpan = hi - lo;
	// Pad so bars/labels don't touch the edges; a floor keeps a flat bridge sane.
	const pad = Math.max(rawSpan * 0.08, Math.abs(hi) * 0.02, 1);

	return {
		rows,
		domainMin: lo - pad,
		domainMax: hi + pad,
		startTotal: priorGrand,
		endTotal: currentGrand,
		year,
		priorYear
	};
}

