import { describe, it, expect } from 'vitest';
import { buildSpendingReport, type SpendingExpense, type SpendingCategory } from './spendingReport';
import type { ImportanceArea, CategoryGroup } from '$lib/types/Hierarchy';
import { buildWaterfallBridge, type WaterfallRow } from './spendingWaterfall';

// --- fixtures ---------------------------------------------------------------

const importanceAreas: ImportanceArea[] = [
	{ id: 'imp-ess', name: 'Essential', sort_order: 1 },
	{ id: 'imp-pri', name: 'Priorities', sort_order: 2 },
	{ id: 'imp-oth', name: 'Other', sort_order: 3 }
];

const groups: CategoryGroup[] = [
	{ id: 'grp-everyday', name: 'Everyday', importance_area_id: 'imp-ess' },
	{ id: 'grp-home', name: 'Home', importance_area_id: 'imp-ess' },
	{ id: 'grp-kids', name: 'Kids', importance_area_id: 'imp-pri' },
	{ id: 'grp-disc', name: 'Discretionary', importance_area_id: 'imp-oth' }
];

const categories: SpendingCategory[] = [
	{ id: 'cat-groceries', name: 'Groceries', group_id: 'grp-everyday' },
	{ id: 'cat-clothes', name: 'Clothes', group_id: 'grp-everyday' },
	{ id: 'cat-utilities', name: 'Utilities', group_id: 'grp-home' },
	{ id: 'cat-allowance', name: 'Allowance', group_id: 'grp-kids' },
	{ id: 'cat-alcohol', name: 'Alcohol', group_id: 'grp-disc' },
	{ id: 'cat-orphan', name: 'Orphan', group_id: null }
];

function expense(overrides: Partial<SpendingExpense>): SpendingExpense {
	return {
		total_amount: 100,
		transaction_date: '2026-01-15',
		category_id: 'cat-groceries',
		exchange_rate_to_cad: null,
		...overrides
	};
}

function bridge(current: SpendingExpense[], prior: SpendingExpense[], expanded: string[] = []) {
	const cur = buildSpendingReport(current, categories, groups, importanceAreas, 2026);
	const pri = buildSpendingReport(prior, categories, groups, importanceAreas, 2025);
	return buildWaterfallBridge(cur, pri, new Set(expanded));
}

const steps = (rows: WaterfallRow[]) => rows.filter((r) => r.kind === 'step');

// --- anchors & reconciliation -----------------------------------------------

describe('anchors and reconciliation', () => {
	it('opens on the prior grand total and closes on the current grand total', () => {
		const r = bridge(
			[
				expense({ category_id: 'cat-groceries', total_amount: 100 }),
				expense({ category_id: 'cat-utilities', total_amount: 200 })
			],
			[expense({ category_id: 'cat-groceries', transaction_date: '2025-01-10', total_amount: 80 })]
		);
		const start = r.rows[0];
		const end = r.rows[r.rows.length - 1];
		expect(start.kind).toBe('anchor-start');
		expect(start.label).toBe('2025');
		expect(start.to).toBe(80); // prior grand total
		expect(end.kind).toBe('anchor-end');
		expect(end.label).toBe('2026');
		expect(end.to).toBe(300); // current grand total
	});

	it('chains each step from the previous running total and lands on the end anchor', () => {
		const r = bridge(
			[
				expense({ category_id: 'cat-groceries', total_amount: 100 }),
				expense({ category_id: 'cat-utilities', total_amount: 200 })
			],
			[expense({ category_id: 'cat-groceries', transaction_date: '2025-01-10', total_amount: 80 })]
		);
		const s = steps(r.rows);
		// Everyday +20 (100 vs 80), Home +200 (200 vs 0).
		expect(s.map((x) => x.delta)).toEqual([20, 200]);
		expect(s[0].from).toBe(80); // starts at the prior grand total
		// Continuity: each step begins where the last ended.
		for (let i = 1; i < s.length; i++) expect(s[i].from).toBe(s[i - 1].to);
		expect(s[s.length - 1].to).toBe(300); // reconciles to the current grand total
	});

	it('the step deltas sum to the change in grand total', () => {
		const r = bridge(
			[expense({ category_id: 'cat-groceries', total_amount: 100 })],
			[expense({ category_id: 'cat-utilities', transaction_date: '2025-01-10', total_amount: 200 })]
		);
		const sum = steps(r.rows).reduce((a, s) => a + s.delta, 0);
		expect(sum).toBe(100 - 200);
	});
});

// --- new vs disappeared areas ------------------------------------------------

describe('new and disappeared areas', () => {
	it('renders a new area (no prior spend) as an upward step', () => {
		const r = bridge(
			[expense({ category_id: 'cat-utilities', total_amount: 200 })],
			[expense({ category_id: 'cat-groceries', transaction_date: '2025-01-10', total_amount: 50 })]
		);
		const home = steps(r.rows).find((s) => s.groupName === 'Home')!;
		expect(home.prior).toBe(0);
		expect(home.current).toBe(200);
		expect(home.direction).toBe('up');
	});

	it('renders a disappeared area (spent last year, nothing this year) as a downward step', () => {
		const r = bridge(
			[expense({ category_id: 'cat-groceries', total_amount: 100 })],
			[expense({ category_id: 'cat-utilities', transaction_date: '2025-01-10', total_amount: 200 })]
		);
		// Home has no current row, but the bridge still steps it down to reconcile.
		const home = steps(r.rows).find((s) => s.groupName === 'Home')!;
		expect(home.current).toBe(0);
		expect(home.prior).toBe(200);
		expect(home.delta).toBe(-200);
		expect(home.direction).toBe('down');
	});
});

// --- ordering ----------------------------------------------------------------

describe('ordering', () => {
	it('orders steps by Importance then group name, with Uncategorized last', () => {
		const r = bridge(
			[
				expense({ category_id: 'cat-alcohol', total_amount: 1 }), // Other / Discretionary
				expense({ category_id: 'cat-allowance', total_amount: 1 }), // Priorities / Kids
				expense({ category_id: 'cat-groceries', total_amount: 1 }), // Essential / Everyday
				expense({ category_id: 'cat-orphan', total_amount: 1 }) // Uncategorized
			],
			[expense({ category_id: 'cat-groceries', transaction_date: '2025-01-10', total_amount: 1 })]
		);
		expect(steps(r.rows).map((s) => s.groupName)).toEqual([
			'Everyday',
			'Kids',
			'Discretionary',
			'Uncategorized'
		]);
	});
});

// --- accordion ---------------------------------------------------------------

describe('accordion', () => {
	it('expands a group into category steps whose deltas sum to the group delta', () => {
		const r = bridge(
			[
				expense({ category_id: 'cat-groceries', total_amount: 60 }),
				expense({ category_id: 'cat-clothes', total_amount: 40 })
			],
			[
				expense({ category_id: 'cat-groceries', transaction_date: '2025-01-10', total_amount: 50 }),
				expense({ category_id: 'cat-clothes', transaction_date: '2025-01-10', total_amount: 10 })
			],
			['Everyday']
		);
		const s = steps(r.rows);
		expect(s.map((x) => x.label)).toEqual(['Clothes', 'Groceries']); // in place, alphabetical
		expect(s.every((x) => x.level === 'category')).toBe(true);
		// Clothes +30 (40 vs 10), Groceries +10 (60 vs 50) → sum 40 = the group delta.
		expect(s.map((x) => x.delta)).toEqual([30, 10]);
		expect(s[0].from).toBe(60); // prior grand total
		expect(s[s.length - 1].to).toBe(100); // still reconciles
	});

	it('leaves sibling groups untouched when one is expanded', () => {
		const r = bridge(
			[
				expense({ category_id: 'cat-groceries', total_amount: 60 }),
				expense({ category_id: 'cat-clothes', total_amount: 40 }),
				expense({ category_id: 'cat-utilities', total_amount: 200 })
			],
			[expense({ category_id: 'cat-groceries', transaction_date: '2025-01-10', total_amount: 50 })],
			['Everyday']
		);
		const s = steps(r.rows);
		// Everyday's two categories, then Home still a single collapsed group step.
		expect(s.map((x) => x.label)).toEqual(['Clothes', 'Groceries', 'Home']);
		const home = s.find((x) => x.label === 'Home')!;
		expect(home.level).toBe('group');
		expect(home.expandable).toBe(true);
	});
});

// --- parity window -----------------------------------------------------------

describe('parity window', () => {
	it('truncates prior spend to the current year’s visible-month window', () => {
		// Current has data only through March → window of 3 months.
		const current = [
			expense({ category_id: 'cat-groceries', transaction_date: '2026-03-10', total_amount: 5 })
		];
		// Prior spent 10 every month Jan–June; only Jan–Mar should count.
		const prior = [1, 2, 3, 4, 5, 6].map((m) =>
			expense({ category_id: 'cat-groceries', transaction_date: `2025-0${m}-10`, total_amount: 10 })
		);
		const r = bridge(current, prior);
		expect(r.rows[0].to).toBe(30); // start anchor = prior grand, truncated to 3 months
		const everyday = steps(r.rows).find((s) => s.groupName === 'Everyday')!;
		expect(everyday.prior).toBe(30);
		expect(everyday.delta).toBe(5 - 30);
	});
});

// --- empty -------------------------------------------------------------------

describe('empty current year', () => {
	it('returns no rows when the current year has no data', () => {
		const r = bridge(
			[],
			[expense({ category_id: 'cat-groceries', transaction_date: '2025-01-10', total_amount: 50 })]
		);
		expect(r.rows).toEqual([]);
	});
});

