function toggleGroup(name: string) {
	if (expandedGroups.has(name)) expandedGroups.delete(name);
	else expandedGroups.add(name);
}

// LayerChart data: a stable unique id per bar (names can repeat across groups,
// which would collide on the band scale), plus the fields the chart reads.
const data = $derived(
	model.bars.map((bar, i) => ({
		id: `b${i}`,
		name: bar.name,
		kind: bar.kind,
		importance: bar.importance,
		total: bar.total
	}))
);

// Validated categorical palette (dataviz), assigned to Importances in report
// order; the no-importance (Uncategorized) bars get a neutral gray.
const IMPORTANCE_PALETTE = ['#4f46e5', '#0d9488', '#d97706', '#7c3aed', '#db2777'];
const NEUTRAL = '#9ca3af';

const importanceColors = $derived.by(() => {
	const domain: string[] = [];
	const range: string[] = [];
	let next = 0;
	for (const bar of model.bars) {
		if (domain.includes(bar.importance)) continue;
		domain.push(bar.importance);
		if (bar.importance === '') {
			range.push(NEUTRAL);
		} else {
			range.push(IMPORTANCE_PALETTE[next % IMPORTANCE_PALETTE.length]);
			next++;
		}
	}
	return { domain, range };
});

const cDomain = $derived(importanceColors.domain);
const cRange = $derived(importanceColors.range);

function importanceColor(name: string): string {
	const idx = importanceColors.domain.indexOf(name);
	return idx >= 0 ? importanceColors.range[idx] : NEUTRAL;
}

// Bound LayerChart state; its scales position the brackets, labels, and toggles.
let chartContext = $state<ChartState | undefined>(undefined);

/** The x-scale is a band scale for categorical bars; AnyScale hides bandwidth. */
interface BandScale {
	(value: string): number | undefined;
	bandwidth(): number;
}
type LinearScale = (value: number) => number;

function bandScale(): BandScale | null {
	const xScale = chartContext?.xScale as unknown as BandScale | undefined;
	return xScale && typeof xScale.bandwidth === 'function' ? xScale : null;
}

// Truncate a tick label to what fits one bar width (~6.5px per char at the tick
// font size); the full name is always available in the hover tooltip.
function fitLabel(name: string): string {
	const bandwidth = bandScale()?.bandwidth() ?? 0;
	const maxChars = Math.max(3, Math.floor(bandwidth / 6.5));
	return name.length > maxChars ? `${name.slice(0, maxChars - 1).trimEnd()}…` : name;
}

interface Span {
	key: string;
	left: number;
	width: number;
}

/** Pixel span of bars [start..end] (inclusive) from the band scale, or null. */
function spanOf(start: number, end: number): Omit<Span, 'key'> | null {
	const ctx = chartContext;
	const xScale = bandScale();
	if (!ctx || !xScale) return null;
	const a = xScale(`b${start}`);
	const b = xScale(`b${end}`);
	if (typeof a !== 'number' || typeof b !== 'number') return null;

