input.new_string:
interface BarBox {
	key: string;
	left: number;
	top: number;
	width: number;
	height: number;
	color: string;
	value: number;
	faded: boolean;
}

// The visible bars, drawn as an overlay from the band + linear scales (LayerChart's
// own bars are hidden via props.bars.opacity). When comparing, each Grouping shows
// two bars side by side: the current year (solid) and the prior year (faded).
const barBoxes = $derived.by((): BarBox[] => {
	const ctx = chartContext;
	const xScale = bandScale();
	const yScale = ctx?.yScale as unknown as LinearScale | undefined;
	if (!ctx || !xScale || typeof yScale !== 'function') return [];
	const bandwidth = xScale.bandwidth();
	const baseline = yScale(0);
	const out: BarBox[] = [];
	const add = (i: number, subLeft: number, subWidth: number, value: number, faded: boolean) => {
		const yTop = yScale(value);
		if (typeof yTop !== 'number' || typeof baseline !== 'number') return;
		out.push({
			key: `${faded ? 'p' : 'c'}${i}`,
			left: ctx.padding.left + subLeft,
			top: ctx.padding.top + Math.min(yTop, baseline), // supports negative (net-refund) bars
			width: subWidth,
			height: Math.abs(baseline - yTop),
			color: importanceColor(model.bars[i].importance),
			value,
			faded
		});
	};
	model.bars.forEach((bar, i) => {
		const x = xScale(`b${i}`);
		if (typeof x !== 'number') return;
		if (compare) {
			const gap = bandwidth * 0.12;
			const w = Math.max((bandwidth - gap) / 2, 1);
			add(i, x, w, bar.total, false); // current year — left, solid
			add(i, x + w + gap, w, bar.priorTotal ?? 0, true); // prior year — right, faded
		} else {
			add(i, x, bandwidth, bar.total, false);
		}
	});
	return out;
});

interface ValueLabel {
	cx: number;
	top: number;
	text: string;
	key: string;
}

// One currency label above each current-year bar (the prior bar's exact value is
// in the hover tooltip), so a tiny bar next to a dominant one is still readable.
const valueLabels = $derived.by((): ValueLabel[] =>
	barBoxes
		.filter((box) => !box.faded && box.value !== 0)
		.map((box) => ({
			key: box.key,
			cx: box.left + box.width / 2,
			top: box.top,
			text: formatCurrency(box.value)
		}))
);

