import { describe, it, expect } from 'vitest';
import { render } from 'vitest-browser-svelte';
import SpendingChart from './SpendingChart.svelte';
import {
	buildSpendingReport,
	type SpendingExpense,
	type SpendingCategory
} from '$lib/utils/spendingReport';
import { withPriorPeriod } from '$lib/utils/spendingComparison';
import type { ImportanceArea, CategoryGroup } from '$lib/types/Hierarchy';

/**
 * Render tests for the real <SpendingChart> on top of LayerChart. Data shaping is
 * unit-tested in spendingChart.spec.ts; these prove the component mounts
 * LayerChart, draws bars + value labels, renders the once-only Importance
 * brackets, and — the interaction — expands a Grouping in place while its
 * siblings stay, with several open at once.
 */

const importanceAreas: ImportanceArea[] = [
	{ id: 'imp-ess', name: 'Essential', sort_order: 1 },
	{ id: 'imp-pri', name: 'Priorities', sort_order: 2 }
];
const groups: CategoryGroup[] = [
	{ id: 'grp-everyday', name: 'Everyday', importance_area_id: 'imp-ess' },
	{ id: 'grp-home', name: 'Home', importance_area_id: 'imp-ess' },
	{ id: 'grp-kids', name: 'Kids', importance_area_id: 'imp-pri' }
];
const categories: SpendingCategory[] = [
	{ id: 'cat-groceries', name: 'Groceries', group_id: 'grp-everyday' },
	{ id: 'cat-clothes', name: 'Clothes', group_id: 'grp-everyday' },
	{ id: 'cat-utilities', name: 'Utilities', group_id: 'grp-home' },
	{ id: 'cat-allowance', name: 'Allowance', group_id: 'grp-kids' }
];

function reportFor(expenses: SpendingExpense[]) {
	return buildSpendingReport(expenses, categories, groups, importanceAreas, 2026);
}

/** A 2026 report with same-period 2025 totals attached, for the comparison view. */
function comparedReport(current: SpendingExpense[], prior: SpendingExpense[]) {
	const report = reportFor(current);
	const priorReport = buildSpendingReport(prior, categories, groups, importanceAreas, 2025);
	return withPriorPeriod(report, priorReport);
}

function amount(
	category_id: string,
	total_amount: number,
	transaction_date = '2026-01-10'
): SpendingExpense {
	return { category_id, transaction_date, total_amount, exchange_rate_to_cad: null };
}

const sample = [
	amount('cat-groceries', 400),
	amount('cat-clothes', 120),
	amount('cat-utilities', 200),
	amount('cat-allowance', 60)
];

describe('SpendingChart', () => {
	it('mounts LayerChart and lays out a bar per grouping', async () => {
		const screen = render(SpendingChart, { report: reportFor(sample) });
		await expect.poll(() => screen.baseElement.querySelectorAll('svg').length).toBeGreaterThan(0);
		// One transparent click column is placed per bar once the band scale resolves;
		// the sample has three groupings (Everyday, Home, Kids).
		await expect
			.poll(() => screen.baseElement.querySelectorAll('button[data-group]').length)
			.toBe(3);
	});

	it('labels each area of importance once as a coloured bracket', async () => {
		const screen = render(SpendingChart, { report: reportFor(sample) });
		// getByText throws on multiple matches, so a bare match proves once-only.
		await expect.element(screen.getByText('ESSENTIAL')).toBeInTheDocument();
		await expect.element(screen.getByText('PRIORITIES')).toBeInTheDocument();
	});

	it('prints a value label on each bar', async () => {
		const screen = render(SpendingChart, { report: reportFor(sample) });
		// Everyday=$520, Home=$200, Kids=$60 when collapsed.
		await expect.element(screen.getByText('$520.00')).toBeInTheDocument();
		await expect.element(screen.getByText('$200.00')).toBeInTheDocument();
		await expect.element(screen.getByText('$60.00')).toBeInTheDocument();
	});

	it('expands a grouping in place while its siblings stay', async () => {
		const screen = render(SpendingChart, { report: reportFor(sample) });
		await screen.getByRole('button', { name: 'Expand Everyday' }).click();
		// Everyday's categories now show...
		await expect.element(screen.getByText('$400.00')).toBeInTheDocument(); // Groceries
		await expect.element(screen.getByText('$120.00')).toBeInTheDocument(); // Clothes
		// ...and the siblings remain as their own bars/brackets.
		await expect.element(screen.getByRole('button', { name: 'Expand Home' })).toBeInTheDocument();
		await expect.element(screen.getByRole('button', { name: 'Expand Kids' })).toBeInTheDocument();
		// The toggle flips to collapse.
		await expect
			.element(screen.getByRole('button', { name: 'Collapse Everyday' }))
			.toBeInTheDocument();
	});

	it('keeps several groupings open at once', async () => {
		const screen = render(SpendingChart, { report: reportFor(sample) });
		await screen.getByRole('button', { name: 'Expand Everyday' }).click();
		await screen.getByRole('button', { name: 'Expand Kids' }).click();
		await expect.element(screen.getByText('$400.00')).toBeInTheDocument(); // Groceries (Everyday)
		await expect.element(screen.getByText('$60.00')).toBeInTheDocument(); // Allowance (Kids)
		// Home stays collapsed.
		await expect.element(screen.getByRole('button', { name: 'Expand Home' })).toBeInTheDocument();
	});

	it('collapses an expanded grouping back to a single bar', async () => {
		const screen = render(SpendingChart, { report: reportFor(sample) });
		await screen.getByRole('button', { name: 'Expand Everyday' }).click();
		const collapse = screen.getByRole('button', { name: 'Collapse Everyday' });
		await expect.element(collapse).toBeInTheDocument();
		// Dispatch directly: LayerChart's bar transition keeps the page "unstable",
		// which would otherwise time out Playwright's actionability wait on .click().
		collapse.element().dispatchEvent(new MouseEvent('click', { bubbles: true }));
		await expect
			.element(screen.getByRole('button', { name: 'Expand Everyday' }))
			.toBeInTheDocument();
	});

	it('expands a grouping when the bar itself (not just the bracket) is clicked', async () => {
		const screen = render(SpendingChart, { report: reportFor(sample) });
		// The transparent per-bar layer (aria-hidden, so found by attribute).
		await expect
			.poll(() => screen.baseElement.querySelectorAll('button[data-group]').length)
			.toBeGreaterThan(0);
		const bar = screen.baseElement.querySelector('button[data-group="Everyday"]')!;
		bar.dispatchEvent(new MouseEvent('click', { bubbles: true }));
		await expect.element(screen.getByText('$400.00')).toBeInTheDocument(); // Groceries
		await expect
			.element(screen.getByRole('button', { name: 'Collapse Everyday' }))
			.toBeInTheDocument();
	});

	it('draws a side-by-side prior-year bar per grouping when comparing', async () => {
		const report = comparedReport(sample, [
			amount('cat-groceries', 300, '2025-01-10'),
			amount('cat-utilities', 150, '2025-01-10'),
			amount('cat-allowance', 40, '2025-01-10')
		]);
		const screen = render(SpendingChart, { report, compare: true });
		// One current + one prior bar per grouping (Everyday, Home, Kids) once scales resolve.
		await expect
			.poll(() => screen.baseElement.querySelectorAll('div[data-bar="prior"]').length)
			.toBe(3);
		expect(screen.baseElement.querySelectorAll('div[data-bar="current"]').length).toBe(3);
	});

	it('adds the prior total and change to the hover tooltip when comparing', async () => {
		const report = comparedReport(sample, [amount('cat-utilities', 150, '2025-01-10')]);
		const screen = render(SpendingChart, { report, compare: true });
		await expect
			.poll(() => screen.baseElement.querySelectorAll('button[data-group]').length)
			.toBeGreaterThan(0);
		const bar = screen.baseElement.querySelector('button[data-group="Home"]')!;
		bar.dispatchEvent(
			new PointerEvent('pointerenter', { bubbles: true, clientX: 40, clientY: 40 })
		);
		const tip = screen.getByRole('tooltip');
		await expect.element(tip).toHaveTextContent('2025'); // prior-year row label
		await expect.element(tip).toHaveTextContent('Change');
		await expect.element(tip).toHaveTextContent('$150.00'); // Home's prior total
	});

	it('omits the prior-period marker when not comparing', async () => {
		const screen = render(SpendingChart, { report: reportFor(sample) });
		await expect
			.poll(() => screen.baseElement.querySelectorAll('button[data-group]').length)
			.toBe(3);
		expect(screen.baseElement.querySelectorAll('div.border-dashed').length).toBe(0);
	});

	it('shows a hover tooltip with the name, month totals and grand total', async () => {
		const screen = render(SpendingChart, { report: reportFor(sample) });
		await expect
			.poll(() => screen.baseElement.querySelectorAll('button[data-group]').length)
			.toBeGreaterThan(0);
		const bar = screen.baseElement.querySelector('button[data-group="Home"]')!;
		bar.dispatchEvent(
			new PointerEvent('pointerenter', { bubbles: true, clientX: 40, clientY: 40 })
		);

		const tip = screen.getByRole('tooltip');
		await expect.element(tip).toBeInTheDocument();
		await expect.element(tip).toHaveTextContent('Home'); // name
		await expect.element(tip).toHaveTextContent('Jan'); // month row
		await expect.element(tip).toHaveTextContent('Total'); // grand-total row
		await expect.element(tip).toHaveTextContent('$200.00'); // Home's amount
	});
});

